/**
 * Kami's concept library: answers to concept questions ("what is miai?", "when is thickness
 * worth more than territory?") with real example positions checked by KataGo. Used by the
 * Kami site, and by scripts/coachlm/factory.ts to make concept training tasks.
 *
 * The texts live in concepts/*.ts (written by hand, reviewed for accuracy); the examples in
 * examples.ts are generated by scripts/concept-examples.ts, which checks every claim with
 * KataGo and drops the ones it disagrees with. See docs/handoff/kami-library.md.
 */
import { sgfToLoc } from '../../go/coords';
import type { Color, Move } from '../../go/types';
import { BASICS } from './concepts/basics';
import { ENDGAME } from './concepts/endgame';
import { OPENING } from './concepts/opening';
import { SHAPE } from './concepts/shape';
import { STRATEGY } from './concepts/strategy';
import { TACTICS } from './concepts/tactics';
import { TEMPO } from './concepts/tempo';
import { EXAMPLE_RECORDS } from './examples';
import type { ConceptEntry, ConceptExample, ConceptText, ExampleRecord } from './types';

export type { ConceptEntry, ConceptExample, ConceptLevel } from './types';

const TEXTS: ConceptText[] = [...BASICS, ...TACTICS, ...SHAPE, ...TEMPO, ...STRATEGY, ...OPENING, ...ENDGAME];

const locs = (s: string, size: number) => {
  const out: number[] = [];
  for (let i = 0; i + 1 < s.length; i += 2) out.push(sgfToLoc(s.slice(i, i + 2), size));
  return out;
};

/** A stored example as a ConceptExample (setup stones, the line as alternating moves). */
export function decodeExample(r: ExampleRecord): ConceptExample {
  const toPlay: Color = r.toPlay === 'B' ? 1 : 2;
  const setup: Move[] = [
    ...locs(r.black, r.size).map((loc): Move => ({ color: 1, loc })),
    ...locs(r.white, r.size).map((loc): Move => ({ color: 2, loc })),
  ];
  const line = locs(r.line, r.size).map((loc, i): Move => ({ color: (i % 2 === 0 ? toPlay : 3 - toPlay) as Color, loc }));
  return {
    title: r.title,
    position: { size: r.size, komi: r.komi, setup, moves: [], toPlay },
    line,
    note: r.note,
    source: r.source,
    ...(r.view ? { view: r.view } : {}),
  };
}

export const CONCEPTS: ConceptEntry[] = TEXTS.map((c) => ({
  ...c,
  examples: EXAMPLE_RECORDS.filter((r) => r.concept === c.id).map(decodeExample),
}));

const BY_ID = new Map(CONCEPTS.map((c) => [c.id, c]));

export function conceptById(id: string): ConceptEntry | undefined {
  return BY_ID.get(id);
}

// ---------------------------------------------------------------------------------------
// Matching. Terms are a concept's name, id and aliases. Latin terms match whole words (with
// simple plurals and -ed/-ing forms); Chinese, Japanese and Korean terms match as substrings.
// Common English words (and single CJK characters) only count when the question is about Go
// at all, and score lower than specific terms. A match inside a longer match of another
// concept ("sente" inside "double sente", "ko" inside "ko threat") is dropped.

/** Lowercase, width- and accent-folded, apostrophes dropped, hyphens and slashes as spaces. */
export function normalizeQuestion(s: string): string {
  return s
    .normalize('NFKC')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .normalize('NFC')
    .replace(/[’‘`´']/g, '')
    .replace(/[-‐‑–—_/]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Terms that are ordinary words outside Go: they need Go context and score low. */
const WEAK = new Set(
  [
    'shape', 'attack', 'attacking', 'eye', 'eyes', 'net', 'light', 'heavy', 'wall', 'influence', 'direction', 'which side',
    'base', 'cap', 'count', 'counting', 'kill', 'killing', 'alive', 'living', 'placement', 'reduce', 'reducing', 'reduction',
    'profit', 'swing', 'tactic', 'tactics', 'squeeze', 'clamp', 'initiative', 'thick', 'inefficient', 'inefficiency',
    'duplication', 'extension', 'enclosure', 'dame', 'cut', 'cutting', 'connect', 'connection', 'connecting', 'race',
    'probe', 'probing', 'urgent', 'opening', 'settling', 'how many points', 'territory',
  ].map(normalizeQuestion),
);

/** Words that show a question is about Go, so weak terms may count. */
const GO_CONTEXT =
  /(?<![a-z0-9])(go|baduk|weiqi|igo|stones?|groups?|moves?|board|corners?|joseki|black|white|kyu|dan|games?|play|plays|played|playing|opponent|katago|kami|positions?|tsumego|edge|liberty|liberties)(?![a-z0-9])|围棋|圍棋|囲碁|바둑|棋|黑|白|흑|백|돌/;

const LATIN = /^[a-z0-9 .]+$/;
const escape = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/** Regex source for a word and its simple inflections (plurals, -ed, -ing, -ies). */
function inflected(word: string): string {
  const forms = new Set([word, `${word}s`, `${word}es`, `${word}d`, `${word}ed`, `${word}ing`]);
  if (word.endsWith('e')) forms.add(`${word.slice(0, -1)}ing`);
  if (word.endsWith('y')) forms.add(`${word.slice(0, -1)}ies`);
  return `(?:${[...forms].sort((a, b) => b.length - a.length).map(escape).join('|')})`;
}

interface Term {
  concept: string;
  text: string;
  weight: number;
  weak: boolean;
  re?: RegExp;
}

function termsOf(c: ConceptText): Term[] {
  const raw = [...c.name.split(/[()]/), c.id, ...c.aliases].map(normalizeQuestion).filter((t) => t.length > 0);
  const out: Term[] = [];
  for (const text of new Set(raw)) {
    const weak = WEAK.has(text);
    if (LATIN.test(text)) {
      const words = text.split(' ');
      const last = words.pop()!;
      const src = [...words.map(escape), inflected(last)].join('\\s+');
      out.push({ concept: c.id, text, weak, weight: weak ? 1 : words.length ? 3 : 2, re: new RegExp(`(?<![a-z0-9])${src}(?![a-z0-9])`, 'g') });
    } else {
      // Chinese, Japanese, Korean: substring; a single character is too ambiguous to be strong.
      const single = [...text.replace(/\s/g, '')].length === 1;
      out.push({ concept: c.id, text, weak: weak || single, weight: weak || single ? 1 : 3 });
    }
  }
  return out;
}

const TERMS: Term[] = TEXTS.flatMap(termsOf);

/** Idioms that use Go words in their everyday sense. */
const IDIOMS = /(?<![a-z0-9])in (?:good|bad|great|poor|terrible|better|worse|top|the best) shape(?![a-z0-9])|(?<![a-z0-9])keep an eye on(?![a-z0-9])|(?<![a-z0-9])(?:safety|social) net(?![a-z0-9])/g;

interface Hit {
  concept: string;
  start: number;
  end: number;
  weight: number;
  weak: boolean;
}

function hitsIn(q: string): Hit[] {
  const hits: Hit[] = [];
  for (const t of TERMS) {
    if (t.re) {
      t.re.lastIndex = 0;
      for (let m = t.re.exec(q); m; m = t.re.exec(q)) hits.push({ concept: t.concept, start: m.index, end: m.index + m[0].length, weight: t.weight, weak: t.weak });
    } else {
      for (let i = q.indexOf(t.text); i >= 0; i = q.indexOf(t.text, i + 1)) hits.push({ concept: t.concept, start: i, end: i + t.text.length, weight: t.weight, weak: t.weak });
    }
  }
  return hits;
}

/** Concepts a question is about, with scores, best first (empty when it names none). */
export function scoreConcepts(text: string): { concept: ConceptEntry; score: number }[] {
  const raw = normalizeQuestion(text);
  const goContext = GO_CONTEXT.test(raw);
  // Outside a Go context, blank out idioms ("in bad shape") with spaces so positions stay aligned.
  const q = goContext ? raw : raw.replace(IDIOMS, (m) => ' '.repeat(m.length));
  let hits = hitsIn(q);
  // A hit inside a longer hit is part of that term ("sente" in "double sente"), not its own.
  hits = hits.filter((h) => !hits.some((o) => o.start <= h.start && o.end >= h.end && o.end - o.start > h.end - h.start));
  const strong = hits.some((h) => !h.weak);
  const words = q.split(' ').filter(Boolean).length;
  const context = strong || words <= 5 || goContext;
  if (!context) hits = hits.filter((h) => !h.weak);
  const by = new Map<string, Hit[]>();
  for (const h of hits) by.set(h.concept, [...(by.get(h.concept) ?? []), h]);
  const scored = [...by.entries()].map(([id, hs]) => {
    const best = Math.max(...hs.map((h) => h.weight));
    const distinct = new Set(hs.map((h) => `${h.start}:${h.end}`)).size;
    return { concept: BY_ID.get(id)!, score: best + 0.25 * (distinct - 1), first: Math.min(...hs.map((h) => h.start)) };
  });
  scored.sort((a, b) => b.score - a.score || a.first - b.first);
  return scored.map(({ concept, score }) => ({ concept, score }));
}

/** Concepts a question is about, best match first (empty when it names none). */
export function findConcepts(text: string): ConceptEntry[] {
  return scoreConcepts(text).map((s) => s.concept);
}
